using System;

namespace Game.Input
{
    /// <summary>
    /// ゲーム内のキー割り当てを保存するためのデータクラス。
    ///
    /// InControlの操作セットから取得した保存文字列を
    /// まとめて管理する。
    ///
    /// 保存処理そのものには依存しない。
    /// </summary>
    [Serializable]
    public sealed class InputBindingSaveData
    {
        /// <summary>
        /// 現在の保存データ形式のバージョン。
        /// </summary>
        public const int CurrentVersion = 1;

        /// <summary>
        /// 保存データのバージョン。
        /// </summary>
        public int Version;

        /// <summary>
        /// ゲーム操作のキー割り当て保存文字列。
        /// </summary>
        public string GameplayBindings;

        /// <summary>
        /// UI操作のキー割り当て保存文字列。
        /// </summary>
        public string UIBindings;

        /// <summary>
        /// 保存データが現在の形式に対応しているか確認する。
        /// </summary>
        /// <returns>
        /// 対応している場合はtrue
        /// </returns>
        public bool IsSupportedVersion()
        {
            return Version == CurrentVersion;
        }

        /// <summary>
        /// 保存データに必要な情報が含まれているか確認する。
        /// </summary>
        /// <returns>
        /// 必要な情報が含まれている場合はtrue
        /// </returns>
        public bool IsValid()
        {
            return IsSupportedVersion() &&
                   !string.IsNullOrWhiteSpace(
                       GameplayBindings) &&
                   !string.IsNullOrWhiteSpace(
                       UIBindings);
        }
    }
}
